#!/usr/bin/env python3
"""Prepare the exact reviewed terminal assets; never run npm or package scripts.

The default command fetches missing archives only. --offline prepares from cache;
--check verifies cache and generated bytes without network access or writes. The
CLI confines both roots to this checkout's ignored build/cache directories.
Imported functions accept temporary roots for isolated policy regression tests.
"""

import argparse
import base64
import gzip
import hashlib
import io
import json
import os
from pathlib import Path, PurePosixPath
import re
import stat
import sys
import tarfile
import tempfile
import time
import urllib.error
import urllib.request


ROOT = Path(__file__).resolve().parents[1]
MANIFEST = ROOT / "qualification/probes/device-baseline/terminal-assets.json"
CACHE_ROOT = ROOT / ".cache/terminal-assets"
OUTPUT_ROOT = ROOT / "qualification/probes/device-baseline/app/build/generated/terminalAssets"
PROVENANCE_PATH = "terminal/notices/provenance.json"
MAX_ARCHIVE_BYTES = 8 * 1024 * 1024
MAX_EXPANDED_BYTES = 32 * 1024 * 1024
MAX_MEMBER_BYTES = 8 * 1024 * 1024
MAX_MEMBERS = 512
MANIFEST_LIMIT = 32 * 1024
EXPECTED = {
    "@xterm/xterm": ("6.0.0", {
        "package/lib/xterm.js": "terminal/vendor/xterm.js",
        "package/css/xterm.css": "terminal/vendor/xterm.css",
        "package/LICENSE": "terminal/notices/xterm-LICENSE.txt",
    }),
    "@xterm/addon-fit": ("0.11.0", {
        "package/lib/addon-fit.js": "terminal/vendor/addon-fit.js",
        "package/LICENSE": "terminal/notices/addon-fit-LICENSE.txt",
    }),
}


class AssetError(ValueError):
    """A failed integrity, archive, destination or offline-admission check."""


def require(condition, message):
    if not condition:
        raise AssetError(message)


def integer(value, minimum, maximum):
    return type(value) is int and minimum <= value <= maximum


def sha256(data):
    return hashlib.sha256(data).hexdigest()


def valid_digest(value):
    return isinstance(value, str) and re.fullmatch(r"[0-9a-f]{64}", value) is not None


def relative_path(value):
    require(isinstance(value, str) and 0 < len(value) <= 300, "Invalid archive/output path")
    require("\\" not in value and all(ord(c) >= 32 and ord(c) != 127 for c in value),
            "Unsafe archive/output path")
    parts = value.split("/")
    require(all(p not in ("", ".", "..") for p in parts), "Noncanonical archive/output path")
    require(not PurePosixPath(value).is_absolute(), "Absolute archive/output path")
    return value


def no_duplicates(pairs):
    result = {}
    for key, value in pairs:
        require(key not in result, "Duplicate JSON field")
        result[key] = value
    return result


def parse_json(data):
    def invalid_constant(_value):
        raise AssetError("Non-finite JSON value")

    try:
        return json.loads(data.decode("utf-8"), object_pairs_hook=no_duplicates,
                          parse_constant=invalid_constant)
    except (UnicodeError, json.JSONDecodeError, RecursionError) as failure:
        raise AssetError("Malformed bounded JSON") from failure


def read_regular(path, limit):
    # NOFOLLOW/NONBLOCK also prevents an accidental FIFO cache entry from hanging
    # before the size/type check. Parent directories are checked separately.
    descriptor = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    with os.fdopen(descriptor, "rb") as stream:
        info = os.fstat(stream.fileno())
        require(stat.S_ISREG(info.st_mode) and 0 <= info.st_size <= limit,
                f"Not a bounded regular file: {path.name}")
        data = stream.read(limit + 1)
    require(len(data) <= limit, f"File grew beyond bound: {path.name}")
    return data


def no_link_components(path):
    """Reject existing symlink components; no concurrent hostile-writer claim."""
    for part in (path, *path.parents):
        try:
            info = part.lstat()
        except FileNotFoundError:
            continue
        require(not stat.S_ISLNK(info.st_mode), f"Symlink destination component: {part.name}")
        require(stat.S_ISDIR(info.st_mode), f"Non-directory destination: {part.name}")


def cli_path(value, permitted_root):
    candidate = Path(os.path.abspath(value))
    require(candidate.is_relative_to(permitted_root), "CLI path is outside its approved ignored root")
    no_link_components(candidate)
    return candidate


def validate_manifest(manifest):
    require(isinstance(manifest, dict) and type(manifest.get("schemaVersion")) is int
            and manifest["schemaVersion"] == 1, "Unsupported terminal asset manifest")
    packages = manifest.get("packages")
    require(isinstance(packages, list) and len(packages) == len(EXPECTED), "Wrong package set")
    names = set()
    for package in packages:
        require(isinstance(package, dict), "Invalid package record")
        name = package.get("name")
        require(isinstance(name, str) and name in EXPECTED and name not in names, "Unapproved/duplicate package")
        names.add(name)
        version, files = EXPECTED[name]
        short_name = name.split("/")[1]
        require(package.get("version") == version and package.get("license") == "MIT", "Package pin changed")
        require(package.get("cacheFile") == f"{short_name}-{version}.tgz", "Invalid cache filename")
        require(package.get("archiveUrl") == f"https://registry.npmjs.org/{name}/-/{short_name}-{version}.tgz",
                "Unapproved archive URL")
        require(integer(package.get("archiveBytes"), 1, MAX_ARCHIVE_BYTES), "Archive size is unbounded")
        require(integer(package.get("archiveMemberCount"), 1, MAX_MEMBERS), "Archive member count is unbounded")
        require(integer(package.get("archiveFileBytes"), 1, MAX_EXPANDED_BYTES), "Archive expansion is unbounded")
        require(valid_digest(package.get("archiveSha256")) and valid_digest(package.get("packageJsonSha256")),
                "Invalid archive/package metadata digest")
        integrity = package.get("integrity")
        require(isinstance(integrity, str) and integrity.startswith("sha512-"), "Missing SHA-512 pin")
        try:
            digest = base64.b64decode(integrity[7:], validate=True)
        except ValueError as failure:
            raise AssetError("Malformed SHA-512 pin") from failure
        require(len(digest) == 64 and base64.b64encode(digest).decode("ascii") == integrity[7:], "Invalid SHA-512 pin")
        selected = package.get("files")
        require(isinstance(selected, list) and len(selected) == len(files), "Wrong selected asset set")
        found = set()
        for asset in selected:
            require(isinstance(asset, dict), "Invalid asset record")
            source = asset.get("archivePath")
            require(isinstance(source, str) and source in files and source not in found, "Unapproved/duplicate asset")
            found.add(source)
            require(asset.get("outputPath") == files[source], "Unapproved asset destination")
            require(integer(asset.get("bytes"), 1, MAX_MEMBER_BYTES) and valid_digest(asset.get("sha256")),
                    "Invalid selected asset bounds/digest")
    notices = manifest.get("additionalNotices")
    require(isinstance(notices, list) and len(notices) <= 8, "Invalid supplementary notice list")
    sources = set()
    for notice in notices:
        require(isinstance(notice, dict), "Invalid supplementary notice")
        source = relative_path(notice.get("sourceFile"))
        asset_path = relative_path(notice.get("assetPath"))
        require(asset_path.startswith("third_party_notices/terminal/")
                and source == "qualification/probes/device-baseline/app/src/main/assets/" + asset_path,
                "Supplementary notice outside the reviewed source directory")
        require(source not in sources, "Duplicate supplementary notice")
        sources.add(source)
        require(integer(notice.get("bytes"), 1, MANIFEST_LIMIT) and valid_digest(notice.get("sha256")),
                "Invalid supplementary notice bounds/digest")
    return manifest


def verify_blob(data, size, digest, label):
    require(len(data) == size and sha256(data) == digest, f"Byte/hash mismatch: {label}")


def extract_assets(package, archive):
    """Inspect the entire bounded archive; materialize only pinned regular members.

    No tar extraction API writes to disk. Bounding decompression *before* parsing
    also bounds PAX/long-name header processing, not merely selected file sizes.
    """
    verify_blob(archive, package["archiveBytes"], package["archiveSha256"], package["name"])
    integrity = "sha512-" + base64.b64encode(hashlib.sha512(archive).digest()).decode("ascii")
    require(integrity == package["integrity"], "Archive SHA-512 mismatch")
    try:
        with gzip.GzipFile(fileobj=io.BytesIO(archive)) as compressed:
            expanded = compressed.read(MAX_EXPANDED_BYTES + 1)
        require(len(expanded) <= MAX_EXPANDED_BYTES, "Archive decompression exceeds bound")
        selected = {asset["archivePath"]: asset for asset in package["files"]}
        seen = set()
        output = {}
        package_json = None
        file_bytes = 0
        with tarfile.open(fileobj=io.BytesIO(expanded), mode="r:") as archive_file:
            for member in archive_file:
                name = relative_path(member.name.rstrip("/") if member.isdir() else member.name)
                require(name == "package" or name.startswith("package/"), "Archive path outside package")
                require(name not in seen, "Duplicate archive member")
                seen.add(name)
                require(len(seen) <= MAX_MEMBERS, "Too many archive members")
                require(member.type in (tarfile.REGTYPE, tarfile.AREGTYPE, tarfile.DIRTYPE)
                        and not member.pax_headers, "Links/special/PAX archive members are forbidden")
                require(integer(member.size, 0, MAX_MEMBER_BYTES), "Archive member exceeds bound")
                require(not member.isdir() or member.size == 0, "Directory carries unexpected payload")
                file_bytes += member.size
                require(file_bytes <= MAX_EXPANDED_BYTES, "Archive file bytes exceed bound")
                if name in selected or name == "package/package.json":
                    require(member.isreg(), "Selected member is not a regular file")
                    with archive_file.extractfile(member) as stream:
                        data = stream.read(member.size + 1)
                    require(len(data) == member.size, "Truncated selected member")
                    if name == "package/package.json":
                        require(len(data) <= MANIFEST_LIMIT, "Package metadata exceeds bound")
                        require(sha256(data) == package["packageJsonSha256"], "Package metadata hash mismatch")
                        package_json = parse_json(data)
                    if name in selected:
                        asset = selected[name]
                        verify_blob(data, asset["bytes"], asset["sha256"], name)
                        output[asset["outputPath"]] = data
        require(len(seen) == package["archiveMemberCount"] and file_bytes == package["archiveFileBytes"],
                "Archive inventory differs from inspection")
        require(len(output) == len(selected), "Selected asset missing from archive")
        require(isinstance(package_json, dict) and package_json.get("name") == package["name"]
                and package_json.get("version") == package["version"] and package_json.get("license") == "MIT"
                and package_json.get("dependencies", {}) == {}, "Package metadata differs from inspected policy")
        return output
    except (OSError, EOFError, tarfile.TarError) as failure:
        raise AssetError("Invalid compressed/tar archive") from failure


class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, request, response, code, message, headers, new_url):
        raise AssetError("Archive redirect refused")


def fetch_archive(package):
    # HTTPS uses the standard verified certificate/hostname path. A redirect or
    # unexpected response never becomes a new authority or an executable step.
    request = urllib.request.Request(package["archiveUrl"], headers={"Accept-Encoding": "identity"})
    opener = urllib.request.build_opener(NoRedirect())
    deadline = time.monotonic() + 120
    with opener.open(request, timeout=20) as response:
        require(response.status == 200 and response.headers.get("Content-Encoding", "identity") == "identity",
                "Unexpected archive HTTP response")
        declared = response.headers.get("Content-Length")
        if declared is not None:
            require(declared == str(package["archiveBytes"]), "Archive HTTP length differs from pin")
        chunks = []
        received = 0
        while True:
            require(time.monotonic() < deadline, "Archive download read deadline exceeded")
            chunk = response.read(min(65536, package["archiveBytes"] + 1 - received))
            if not chunk:
                break
            chunks.append(chunk)
            received += len(chunk)
            require(received <= package["archiveBytes"], "Archive download exceeds pin")
    return b"".join(chunks)


def atomic_write(path, data):
    no_link_components(path.parent)
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = None
    try:
        with tempfile.NamedTemporaryFile(prefix=".terminal-asset-", dir=path.parent, delete=False) as stream:
            temporary = Path(stream.name)
            stream.write(data)
        os.chmod(temporary, 0o644)
        os.replace(temporary, path)
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def inspect_output_tree(output, files):
    no_link_components(output)
    if not output.exists():
        return
    allowed_dirs = {str(p) for name in files for p in PurePosixPath(name).parents if str(p) != "."}
    count = 0
    def unreadable_directory(failure):
        raise failure  # A skipped directory could hide an unreviewed APK asset.

    for directory, directories, filenames in os.walk(output, followlinks=False, onerror=unreadable_directory):
        for name in directories + filenames:
            count += 1
            require(count <= len(files) + len(allowed_dirs), "Unexpected generated asset tree entries")
            path = Path(directory) / name
            relative = path.relative_to(output).as_posix()
            info = path.lstat()
            require(not stat.S_ISLNK(info.st_mode), "Generated asset tree contains a symlink")
            require((relative in allowed_dirs and stat.S_ISDIR(info.st_mode))
                    or (relative in files and stat.S_ISREG(info.st_mode)), "Unexpected generated asset tree entry")


def prepare_assets(manifest, cache, output, *, repository=ROOT, check=False, offline=False):
    validate_manifest(manifest)
    no_link_components(cache)
    assets = {}
    for notice in manifest["additionalNotices"]:
        path = repository / notice["sourceFile"]
        no_link_components(path.parent)
        verify_blob(read_regular(path, MANIFEST_LIMIT), notice["bytes"], notice["sha256"], path.name)
    for package in manifest["packages"]:
        path = cache / package["cacheFile"]
        try:
            archive = read_regular(path, MAX_ARCHIVE_BYTES)
        except FileNotFoundError:
            require(not check and not offline, f"Pinned archive missing in offline mode: {path.name}")
            archive = fetch_archive(package)
            extracted = extract_assets(package, archive)
            atomic_write(path, archive)  # Never cache an unverified HTTP body.
        else:
            extracted = extract_assets(package, archive)  # Corrupt cache is an error, not an automatic replacement.
        assets.update(extracted)
    assets[PROVENANCE_PATH] = (json.dumps(manifest, indent=2, ensure_ascii=True) + "\n").encode("utf-8")
    require(len(assets[PROVENANCE_PATH]) <= MANIFEST_LIMIT, "Generated provenance exceeds bound")
    inspect_output_tree(output, assets)
    # Validate all packages before touching output. A partial filesystem write is
    # not accepted: the build runs --check over every exact generated byte.
    for name, expected in assets.items():
        path = output / name
        if check:
            require(read_regular(path, MAX_MEMBER_BYTES) == expected, f"Generated asset mismatch: {name}")
        else:
            try:
                current = read_regular(path, MAX_MEMBER_BYTES)
            except FileNotFoundError:
                current = None
            if current != expected:
                atomic_write(path, expected)
            require(read_regular(path, MAX_MEMBER_BYTES) == expected, f"Generated asset readback mismatch: {name}")
    return {name: {"bytes": len(data), "sha256": sha256(data)} for name, data in assets.items()}


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, default=OUTPUT_ROOT)
    parser.add_argument("--cache", type=Path, default=CACHE_ROOT)
    modes = parser.add_mutually_exclusive_group()
    modes.add_argument("--check", action="store_true", help="Offline read-only verification; fail if any input/output is missing")
    modes.add_argument("--offline", action="store_true", help="Prepare from the pinned cache without downloading")
    args = parser.parse_args(argv)
    try:
        output = cli_path(args.output, OUTPUT_ROOT)
        cache = cli_path(args.cache, CACHE_ROOT)
        manifest = validate_manifest(parse_json(read_regular(MANIFEST, MANIFEST_LIMIT)))
        result = prepare_assets(manifest, cache, output, check=args.check, offline=args.offline)
    except (AssetError, OSError, urllib.error.URLError) as failure:
        print(f"Terminal asset preparation failed: {failure}", file=sys.stderr)
        return 1
    print(json.dumps({"mode": "check" if args.check else "prepare", "files": result}, indent=2))
    return 0


if __name__ == "__main__":
    sys.exit(main())
